-- Add dependent filters (Geographic Level, Geographic Zone, Facility Type) to `Inventaire ECF`
UPDATE report.jasper_templates
SET data = '\'
WHERE name = 'Inventaire ECF';

DELETE FROM report.jasper_template_parameter_dependencies d
USING report.template_parameters p, report.jasper_templates t
WHERE d.parameterid = p.id AND p.templateid = t.id AND t.name = 'Inventaire ECF';

DELETE FROM report.template_parameters p
USING report.jasper_templates t
WHERE p.templateid = t.id AND t.name = 'Inventaire ECF';

INSERT INTO report.template_parameters
    (id, templateid, name, displayname, description,
     selectexpression, selectproperty, displayproperty, required, datatype)
SELECT v.id, t.id, v.name, v.displayname, v.description,
       v.selexpr, v.selprop, v.dispprop, v.required, 'java.lang.String'
FROM report.jasper_templates t,
    (VALUES
        (1, 'affbaf34-f3e5-40fb-bcf4-7bd12907427e'::uuid, 'date', 'Date', 'datepickers', NULL::text, NULL::text, NULL::text, true),
        (2, '94fc5248-6af8-40fe-bcca-cd69334d9de9'::uuid, 'geographicLevel', 'Geographic Level', NULL, '/api/geographicLevels', 'levelNumber', 'name', false),
        (3, 'c92b1e36-f885-4a47-ade1-070b96eabb16'::uuid, 'geographicZone', 'Geographic Zone', NULL, '/api/geographicZones', 'id', 'name', false),
        (4, '4eb55e50-f6c0-4ccf-aa28-889ae865ccbb'::uuid, 'facilityType', 'Facility Type', NULL, '/api/facilityTypes', 'code', 'name', false),
        (5, '0ad44081-8c47-4c1b-a69d-ef17ebbc1bac'::uuid, 'facility', 'Facility', NULL, '/api/facilities?recurse=true', 'name', NULL, false),
        (6, '0e0df573-22cf-403d-b331-0f1c70d29214'::uuid, 'program', 'Program', NULL, '/api/programs', 'name', NULL, false)
    ) AS v(ord, id, name, displayname, description, selexpr, selprop, dispprop, required)
WHERE t.name = 'Inventaire ECF'
ORDER BY v.ord;

INSERT INTO report.jasper_template_parameter_dependencies
    (id, parameterid, dependency, property, placeholder)
SELECT v.id, v.parameterid, v.dependency, v.property, v.placeholder
FROM (VALUES
        ('26d19cc8-3f0c-442d-9d5d-e9f1ca262e3d'::uuid, 'c92b1e36-f885-4a47-ade1-070b96eabb16'::uuid, 'geographicLevel', 'levelNumber', 'levelNumber'),
        ('64599a7b-2498-4a5e-9b95-8f6bb8690675'::uuid, '0ad44081-8c47-4c1b-a69d-ef17ebbc1bac'::uuid, 'facilityType', 'code', 'type'),
        ('aae4b4ba-215c-4e58-bc15-939aaf44dbaa'::uuid, '0ad44081-8c47-4c1b-a69d-ef17ebbc1bac'::uuid, 'geographicZone', 'id', 'zoneId')
